export function generateResourceID(e="#"){const r=new Uint8Array(16);globalThis.crypto.getRandomValues(r);const t=Array.from(r,e=>e.toString(16).padStart(2,"0")).join("");return e+t.slice(0,8)+"-"+t.slice(8,12)+"-"+t.slice(12,16)+"-"+t.slice(16,20)+"-"+t.slice(20)}